              "{\"headline\":\"After US-China clash at APEC, all eyes shift to the Trump-Xi meeting in Argentina\",\"dateCreated\":\"2018-11-19T05:09:21+0000\",\"datePublished\":\"2018-11-19T05:09:21+0000\",\"dateModified\":\"2018-11-19T05:09:21+0000\",\"author\":[{\"name\":\"Yen Nee Lee\"}],\"publisher\":{\"name\":\"CNBC\",\"foundingDate\":\"1989-04-17\",\"sameAs\":[\"https://www.facebook.com/cnbc\",\"https://www.instagram.com/cnbc\",\"https://www.linkedin.com/company/cnbc\",\"https://twitter.com/cnbc\",\"https://en.wikipedia.org/wiki/CNBC\",\"https://www.youtube.com/cnbc\"]},\"articleSection\":\"Politics\",\"keywords\":[\"cnbc\",\"Articles\",\"Trade\",\"International Monetary Fund\",\"Buenos Aires\",\"Argentina\",\"United States\",\"Canada\",\"Mexico\",\"China\",\"Xi Jinping\",\"Donald J. Trump\",\"Economy\",\"World economy\",\"Politics\",\"Asia Economy\",\"Asia News\",\"World Economy\",\"US: News\",\"Asia Politics\",\"World Politics\",\"source:tagname:CNBC Asia Source\"],\"video\":{\"description\":\"Paul Gruenwald of S&P Global Ratings says he's watching the upcoming meeting between U.S. President Donald Trump and Chinese President Xi Jinping at the G-20 summit in Argentina.\",\"duration\":\"PT3M6S\",\"name\":\"Trade war is the number one risk to global outlook, S&P says\",\"uploadDate\":\"2018-11-16T10:22:40+0000\"}}"
            ]
